-- Migration: package update policy — how shared-package updates reach each
-- project, and the Dependabot pull requests Loki applies it to
-- (src/lib/packages/updates.ts, src/config/package-updates.ts).
--
-- Generated by `pnpm run db:generate` from the 0098 snapshot; reviewed by hand.
-- Additive only, nothing existing is rewritten or dropped:
--   * package_update_requests — new table, one row per (project, PR number).
--   * user_projects.package_updates — NOT NULL DEFAULT 'auto'. A constant
--     default is a metadata-only change on PostgreSQL 11+, so no table rewrite.
--     Every existing project starts on "auto", which is what already happened
--     to its non-breaking Dependabot PRs (the fleet sweep merges them on green);
--     breaking ones were already left for a person, and still are. No CHECK
--     constraint: the values are owned by the TS config, as for
--     entities.auto_inject_mode_override (0023), and an unknown value reads as
--     "ask" (readPackageUpdateSetting).
--   * project_packages.dep_name — nullable; filled by the next read of each
--     repository.
CREATE TABLE "package_update_requests" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"user_id" uuid NOT NULL,
	"project_id" uuid NOT NULL,
	"pr_number" integer NOT NULL,
	"pr_url" text NOT NULL,
	"title" text NOT NULL,
	"head_sha" text,
	"packages" jsonb NOT NULL,
	"ci_state" text DEFAULT 'unknown' NOT NULL,
	"state" text DEFAULT 'open' NOT NULL,
	"held_by_loki" boolean DEFAULT false NOT NULL,
	"decision" text,
	"decided_at" timestamp with time zone,
	"snoozed_until" timestamp with time zone,
	"detail" text,
	"opened_at" timestamp with time zone,
	"observed_at" timestamp with time zone DEFAULT now() NOT NULL
);
